// Ported from the Node app's Sequelize model PeriodAttendance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PeriodAttendanceConfiguration : IEntityTypeConfiguration<PeriodAttendance>
{
    public void Configure(EntityTypeBuilder<PeriodAttendance> builder)
    {
        builder.ToTable("period_attendance", t =>
        {
            t.HasCheckConstraint("CK_period_attendance_status", "[status] IN (N'present', N'absent', N'late')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.ClassId).HasColumnName("class_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Period).HasColumnName("period");
        builder.Property(e => e.SubjectId).HasColumnName("subject_id");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired();
        builder.HasIndex(e => new { e.StudentId, e.Date, e.Period }).IsUnique().HasDatabaseName("uq_period_att");
        builder.HasOne(e => e.Student).WithMany(p => p.PeriodAttendances).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
